package snellv6

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"io"
	"testing"

	snell "github.com/sagernet/sing-snell"
)

func helloCostWire(tb testing.TB, key []byte, sizes []int) []byte {
	tb.Helper()
	salt := bytes.Repeat([]byte{0xb1}, saltLen)
	aead, err := snell.NewAEAD(snell.DeriveKey(key, salt))
	if err != nil {
		tb.Fatal(err)
	}
	w := newShapedWriter(io.Discard, NewProfile(key), salt, aead, make([]byte, snell.NonceLen))
	var wire []byte
	for i, n := range sizes {
		r := w.makeSliceRecord(bytes.Repeat([]byte{byte(i + 11)}, n))
		wire = append(wire, r.Bytes()...)
		r.Release()
	}
	return wire
}

// Fixed salts and public keys make this a byte-level compatibility fingerprint
// against the previous candidate, including fallback/multi-record selection.
func TestHelloEncodingCompatibilityDigest(t *testing.T) {
	hash := sha256.New()
	cases := 0
	for k := 0; k < 8; k++ {
		key := []byte(fmt.Sprintf("public hello wire compatibility fixture %d", k))
		codec := newHelloRecordCodec(key)
		for _, sizes := range [][]int{{0}, {1}, {512}, {16, 512}, {16, 2048}, {1, 0, 2, 128, 0, 512}, {40000}} {
			wire := helloCostWire(t, key, sizes)
			for _, budget := range []int{171, 411, 1095, 1115, 1307, 4096} {
				packed, take, mode, err := codec.Pack(wire, budget)
				if err != nil {
					t.Fatal(k, sizes, budget, err)
				}
				fmt.Fprintf(hash, "%d/%v/%d/%d/%d/%x\n", k, sizes, budget, take, mode, packed)
				restored, err := codec.Unpack(packed)
				if err != nil || !bytes.Equal(restored, wire[:take]) {
					t.Fatal("wire identity", k, sizes, budget, err)
				}
				frame, err := helloRecord(packed, true)
				if err != nil {
					t.Fatal(err)
				}
				clear(frame[11:43]) // Only the envelope random changes each call.
				hash.Write(frame)
				cases++
			}
		}
	}
	t.Logf("compatibility_cases=%d sha256=%x", cases, hash.Sum(nil))
	// Generated by e623ade4 before the cost-only changes. This checks both the
	// packed prefix and the envelope, with only its random field normalized.
	if got := fmt.Sprintf("%x", hash.Sum(nil)); got != "bdfec410ce4a085cd83f6d63eae0c74fbdb7aec537d86d2eae2778febeb1e4fd" {
		t.Fatalf("wire compatibility changed: %s", got)
	}
}

var helloBenchmarkSink []byte

func BenchmarkHelloCost(b *testing.B) {
	key := []byte("public hello encoding cost fixture key")
	codec := newHelloRecordCodec(key)
	transport, err := NewHelloTransport(key)
	if err != nil {
		b.Fatal(err)
	}
	for _, tc := range []struct {
		name   string
		sizes  []int
		budget int
	}{
		{"single512", []int{512}, 1115},
		{"multi512", []int{16, 512}, 1115},
		{"partial2048", []int{16, 2048}, 1115},
		{"multiEmpty", []int{1, 0, 2, 128, 0, 512}, 1307},
	} {
		wire := helloCostWire(b, key, tc.sizes)
		packed, _, _, err := codec.Pack(wire, tc.budget)
		if err != nil {
			b.Fatal(err)
		}
		frame, err := helloRecord(packed, true)
		if err != nil {
			b.Fatal(err)
		}
		b.Run(tc.name, func(b *testing.B) {
			b.Run("Encode", func(b *testing.B) {
				b.ReportAllocs()
				for b.Loop() {
					p, _, _, err := codec.Pack(wire, tc.budget)
					if err != nil {
						b.Fatal(err)
					}
					helloBenchmarkSink, err = helloRecord(p, true)
					if err != nil {
						b.Fatal(err)
					}
				}
			})
			b.Run("Decode", func(b *testing.B) {
				b.ReportAllocs()
				for b.Loop() {
					var err error
					helloBenchmarkSink, err = transport.DecodeHello(bytes.NewReader(frame))
					if err != nil {
						b.Fatal(err)
					}
				}
			})
		})
	}
}
